mapper.select:
WITH RECURSIVE menu_tree AS ( SELECT m.menu_seq, m.up_menu_seq, m.menu_nm, m.menu_url, m.menu_type_cd, m.icon_class, m.sort_ord, m.use_yn, 1 AS tree_lvl, LPAD(COALESCE(m.sort_ord, 0)::text, 10, '0') || ':' || LPAD(m.menu_seq::text, 20, '0') AS sort_path FROM adm_menu_mst m WHERE ( m.up_menu_seq IS NULL OR NOT EXISTS ( SELECT 1 FROM adm_menu_mst p WHERE p.menu_seq = m.up_menu_seq
AND p.use_yn = #{use_yn}
) )
AND m.use_yn = #{use_yn}
UNION ALL SELECT c.menu_seq, c.up_menu_seq, c.menu_nm, c.menu_url, c.menu_type_cd, c.icon_class, c.sort_ord, c.use_yn, p.tree_lvl + 1, p.sort_path || '/' || LPAD(COALESCE(c.sort_ord, 0)::text, 10, '0') || ':' || LPAD(c.menu_seq::text, 20, '0') FROM adm_menu_mst c JOIN menu_tree p ON p.menu_seq = c.up_menu_seq
WHERE c.use_yn = #{use_yn}
) SELECT menu_seq, up_menu_seq, menu_nm, menu_url, menu_type_cd, icon_class, sort_ord, use_yn, tree_lvl FROM menu_tree ORDER BY sort_path
